+                                    modulePath -> additionalDependencies.add(
+                                        useExploded
+                                            ? getExplodedBundleDependency(project, modulePath)
+                                            : getBundleZipTaskDependency(project, modulePath)
+                                    )
+                                );
+                            }
+                        }
+                    }
