+            // run compatibility tests after "normal" tests
+            testTask.mustRunAfter(project.getTasks().named(LegacyYamlRestTestPlugin.SOURCE_SET_NAME));
+            testTask.onlyIf(t -> isEnabled(extraProperties));
+        });
